GO

ALTER TABLE __mj_BizAppsOrders.OrderHeader
    ADD CONSTRAINT FK_OrderHeader_ReversesOrder
    FOREIGN KEY (ReversesOrderHeaderID) REFERENCES __mj_BizAppsOrders.OrderHeader(ID);
GO

ALTER TABLE __mj_BizAppsOrders.OrderLine
    ADD CONSTRAINT FK_OrderLine_ReversesOrderLine
    FOREIGN KEY (ReversesOrderLineID) REFERENCES __mj_BizAppsOrders.OrderLine(ID);
