ALTER TABLE __mj_BizAppsOrders.OrderHeader
    ADD CONSTRAINT FK_OrderHeader_ShipToPerson
    FOREIGN KEY (ShipToPersonID) REFERENCES __mj_BizAppsCommon.Person(ID);
